INSERT INTO collection_pages VALUES('0e86a53ed11accac94dbd3dc3d4557dc8bfc7a3b843158e3972803ba26759d75','b3aebd68858865c120598b6236098afbccab1ec03ffa181f7a17d97b6a7f54c9','{"hasNext":false,"items":[{"author":{"account":{"login":"dwang-CXDO","providerType":"User"},"email":"dwang@crexendo.com","name":"David Wang"},"authoredDate":"2026-09-15T00:11:24Z","committedDate":"2026-09-15T00:11:24Z","committer":{"account":{"login":"dwang-CXDO","providerType":"User"},"email":"dwang@crexendo.com","name":"David Wang"},"observedAt":"2026-10-09T00:36:53.383Z","repositoryId":1364884981,"sha":"a863e4f13ff78ef281c776393c7f3c6f81d76e56"},{"author":{"account":{"login":"dwang-CXDO","providerType":"User"},"email":"dwang@crexendo.com","name":"David Wang"},"authoredDate":"2026-09-10T22:39:14Z","committedDate":"2026-09-10T22:39:14Z","committer":{"account":{"login":"dwang-CXDO","providerType":"User"},"email":"dwang@crexendo.com","name":"David Wang"},"observedAt":"2026-10-09T00:36:53.383Z","repositoryId":1364884981,"sha":"b02199b6e6533f238a3c6bbc089059d49c30f9c6"}],"observedAt":"2026-10-09T00:36:53.383Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8418101?v=4","events_url":"https://api.github.com/users/dwang-CXDO/events{/privacy}","followers_url":"https://api.github.com/users/dwang-CXDO/followers","following_url":"https://api.github.com/users/dwang-CXDO/following{/other_user}","gists_url":"https://api.github.com/users/dwang-CXDO/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dwang-CXDO","id":8418101,"login":"dwang-CXDO","node_id":"MDQ6VXNlcjg0MTgxMDE=","organizations_url":"https://api.github.com/users/dwang-CXDO/orgs","received_events_url":"https://api.github.com/users/dwang-CXDO/received_events","repos_url":"https://api.github.com/users/dwang-CXDO/repos","site_admin":false,"starred_url":"https://api.github.com/users/dwang-CXDO/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dwang-CXDO/subscriptions","type":"User","url":"https://api.github.com/users/dwang-CXDO","user_view_type":"public"},"comments_url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/commits/a863e4f13ff78ef281c776393c7f3c6f81d76e56/comments","commit":{"author":{"date":"2026-09-15T00:11:24Z","email":"dwang@crexendo.com","name":"David Wang"},"comment_count":0,"committer":{"date":"2026-09-15T00:11:24Z","email":"dwang@crexendo.com","name":"David Wang"},"message":"Add \"Set as my avatar\" to the detail panel\n\nUploads the artwork the panel is showing — including the sprite fallback for\nforms with no official artwork — as the signed-in user''s avatar, through\nhorizonContext.api so the app never sees the user''s token and the write is\nattributed to it on Registered Apps.\n\nThe upload is multipart/form-data with the field named `file`: the avatar\nendpoint reads a PHP file upload, and the host''s api client passes a FormData\nbody to fetch untouched, setting no Content-Type so the browser writes the\nboundary. The endpoint also requires a square image — PokeAPI artwork is\n475x475 and the sprites 96x96, so both pass.\n\nThree failure modes are handled where the user can see them rather than in a\nconsole: no extension on the session disables the button with a note, a 403\nfrom the proxy says API write access may be off platform-wide, and a 400 names\nthe square-image rule. The result is tagged with the Pokemon it was for, so a\nsuccess message cannot linger under the next Pokemon''s name when the selection\nchanges — the same trap the artwork URL hit.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01JnPtsHsXzbApqMpY6k4Pm9","tree":{"sha":"b545941f8437defa28fb12fccb3e72b3089b1acd","url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/git/trees/b545941f8437defa28fb12fccb3e72b3089b1acd"},"url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/git/commits/a863e4f13ff78ef281c776393c7f3c6f81d76e56","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8418101?v=4","events_url":"https://api.github.com/users/dwang-CXDO/events{/privacy}","followers_url":"https://api.github.com/users/dwang-CXDO/followers","following_url":"https://api.github.com/users/dwang-CXDO/following{/other_user}","gists_url":"https://api.github.com/users/dwang-CXDO/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dwang-CXDO","id":8418101,"login":"dwang-CXDO","node_id":"MDQ6VXNlcjg0MTgxMDE=","organizations_url":"https://api.github.com/users/dwang-CXDO/orgs","received_events_url":"https://api.github.com/users/dwang-CXDO/received_events","repos_url":"https://api.github.com/users/dwang-CXDO/repos","site_admin":false,"starred_url":"https://api.github.com/users/dwang-CXDO/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dwang-CXDO/subscriptions","type":"User","url":"https://api.github.com/users/dwang-CXDO","user_view_type":"public"},"html_url":"https://github.com/netsapiens/horizon-pokemon-app/commit/a863e4f13ff78ef281c776393c7f3c6f81d76e56","node_id":"C_kwDOUVp99doAKGE4NjNlNGYxM2ZmNzhlZjI4MWM3NzYzOTNjN2YzYzZmODFkNzZlNTY","parents":[{"html_url":"https://github.com/netsapiens/horizon-pokemon-app/commit/b02199b6e6533f238a3c6bbc089059d49c30f9c6","sha":"b02199b6e6533f238a3c6bbc089059d49c30f9c6","url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/commits/b02199b6e6533f238a3c6bbc089059d49c30f9c6"}],"sha":"a863e4f13ff78ef281c776393c7f3c6f81d76e56","url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/commits/a863e4f13ff78ef281c776393c7f3c6f81d76e56"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8418101?v=4","events_url":"https://api.github.com/users/dwang-CXDO/events{/privacy}","followers_url":"https://api.github.com/users/dwang-CXDO/followers","following_url":"https://api.github.com/users/dwang-CXDO/following{/other_user}","gists_url":"https://api.github.com/users/dwang-CXDO/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dwang-CXDO","id":8418101,"login":"dwang-CXDO","node_id":"MDQ6VXNlcjg0MTgxMDE=","organizations_url":"https://api.github.com/users/dwang-CXDO/orgs","received_events_url":"https://api.github.com/users/dwang-CXDO/received_events","repos_url":"https://api.github.com/users/dwang-CXDO/repos","site_admin":false,"starred_url":"https://api.github.com/users/dwang-CXDO/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dwang-CXDO/subscriptions","type":"User","url":"https://api.github.com/users/dwang-CXDO","user_view_type":"public"},"comments_url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/commits/b02199b6e6533f238a3c6bbc089059d49c30f9c6/comments","commit":{"author":{"date":"2026-09-10T22:39:14Z","email":"dwang@crexendo.com","name":"David Wang"},"comment_count":0,"committer":{"date":"2026-09-10T22:39:14Z","email":"dwang@crexendo.com","name":"David Wang"},"message":"Pokemon: a Horizon app for a Pokedex page under Apps\n\nA Module Federation remote built with @netsapiens/horizon-sdk 0.2.x that adds a\nPokemon page to the Horizon portal''s Apps menu, alongside Example CRM from\nhorizon-sdk-demo. Search the whole dex index (fetched once from PokeAPI and\nfiltered client-side), a card grid that pages in 60 at a time, and a detail\npanel with official artwork, the English Pokedex entry, types and base stats.\n\nThe data source is public HTTPS with no credential, so there is no proxy and no\nserver-side component: static files on a CDN plus one registration row are the\nwhole install. Card artwork is addressed on the sprite CDN by dex number, so a\nfull grid costs no API calls.\n\nSDK 0.2.x conventions throughout: chunk SRI, source maps with sourcesContent,\nthe SDK kept out of webpack `shared`, a single-sourced federation name, the\ncontextRef page wrapper that keeps `ui` live across a colour-mode toggle, and\nevery visible element from horizonContext.ui.\n\nPublished to GitHub Pages by .github/workflows/deploy-pages.yml on every push to\nmain, guarded by the rule that changed bundle inputs must carry a version bump —\nnew bytes under an unchanged version leave the platform pinning the old hash at\na stable URL, which takes the app off every host with no verdict to explain it.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01JnPtsHsXzbApqMpY6k4Pm9","tree":{"sha":"d364fc51c17ff55a35865920e8e16b53807710f6","url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/git/trees/d364fc51c17ff55a35865920e8e16b53807710f6"},"url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/git/commits/b02199b6e6533f238a3c6bbc089059d49c30f9c6","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8418101?v=4","events_url":"https://api.github.com/users/dwang-CXDO/events{/privacy}","followers_url":"https://api.github.com/users/dwang-CXDO/followers","following_url":"https://api.github.com/users/dwang-CXDO/following{/other_user}","gists_url":"https://api.github.com/users/dwang-CXDO/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dwang-CXDO","id":8418101,"login":"dwang-CXDO","node_id":"MDQ6VXNlcjg0MTgxMDE=","organizations_url":"https://api.github.com/users/dwang-CXDO/orgs","received_events_url":"https://api.github.com/users/dwang-CXDO/received_events","repos_url":"https://api.github.com/users/dwang-CXDO/repos","site_admin":false,"starred_url":"https://api.github.com/users/dwang-CXDO/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dwang-CXDO/subscriptions","type":"User","url":"https://api.github.com/users/dwang-CXDO","user_view_type":"public"},"html_url":"https://github.com/netsapiens/horizon-pokemon-app/commit/b02199b6e6533f238a3c6bbc089059d49c30f9c6","node_id":"C_kwDOUVp99doAKGIwMjE5OWI2ZTY1MzNmMjM4YTNjNmJiYzA4OTA1OWQ0OWMzMGY5YzY","parents":[],"sha":"b02199b6e6533f238a3c6bbc089059d49c30f9c6","url":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/commits/b02199b6e6533f238a3c6bbc089059d49c30f9c6"}],"requestUrl":"https://api.github.com/repos/netsapiens/horizon-pokemon-app/commits?per_page=100&page=1&sha=a863e4f13ff78ef281c776393c7f3c6f81d76e56&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A20%3A01.667Z"}');
