INSERT INTO collection_pages VALUES('cd2bb34786599a9e21b71dc79cd75748abc0383d474271049223fa5ab41e9a17','c6345e2f29f82bb025c052b2bb1918de9d924279b21088f434d727139f492157','{"hasNext":false,"items":[{"author":{"account":{"login":"rohit-manora","providerType":"User"},"email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"authoredDate":"2026-09-11T18:33:09Z","committedDate":"2026-09-11T18:33:09Z","committer":{"account":{"login":"rohit-manora","providerType":"User"},"email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"observedAt":"2026-10-09T00:37:43.428Z","repositoryId":1366536487,"sha":"75d2a67f54b5957f33bea24e1c0f216fcc3d6c89"},{"author":{"account":{"login":"rohit-manora","providerType":"User"},"email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"authoredDate":"2026-09-11T17:48:09Z","committedDate":"2026-09-11T17:48:09Z","committer":{"account":{"login":"rohit-manora","providerType":"User"},"email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"observedAt":"2026-10-09T00:37:43.428Z","repositoryId":1366536487,"sha":"d67a11a9e9d767ce97762f4b866132088226f2a5"}],"observedAt":"2026-10-09T00:37:43.428Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/87164320?v=4","events_url":"https://api.github.com/users/rohit-manora/events{/privacy}","followers_url":"https://api.github.com/users/rohit-manora/followers","following_url":"https://api.github.com/users/rohit-manora/following{/other_user}","gists_url":"https://api.github.com/users/rohit-manora/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/rohit-manora","id":87164320,"login":"rohit-manora","node_id":"MDQ6VXNlcjg3MTY0MzIw","organizations_url":"https://api.github.com/users/rohit-manora/orgs","received_events_url":"https://api.github.com/users/rohit-manora/received_events","repos_url":"https://api.github.com/users/rohit-manora/repos","site_admin":false,"starred_url":"https://api.github.com/users/rohit-manora/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/rohit-manora/subscriptions","type":"User","url":"https://api.github.com/users/rohit-manora","user_view_type":"public"},"comments_url":"https://api.github.com/repos/rohit-manora/portfolio/commits/75d2a67f54b5957f33bea24e1c0f216fcc3d6c89/comments","commit":{"author":{"date":"2026-09-11T18:33:09Z","email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"comment_count":0,"committer":{"date":"2026-09-11T18:33:09Z","email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"message":"Fix build failure when NEXT_PUBLIC_SITE_URL is set but blank\n\n`process.env.NEXT_PUBLIC_SITE_URL ?? FALLBACK` only substitutes the\nfallback for null/undefined. A variable that exists with an empty value\npasses straight through, so SITE_URL became \"\" and `new URL(\"\")` threw\nERR_INVALID_URL while collecting page data, failing the production build.\n\nReplace the nullish coalesce with a resolver that walks a list of\ncandidates and skips any that are blank, whitespace-only or unparseable:\n\n  NEXT_PUBLIC_SITE_URL -> VERCEL_PROJECT_PRODUCTION_URL -> fallback\n\nReading Vercel''s own production domain means a deploy now works with no\nenvironment configuration at all; the explicit variable is only needed\nfor a custom domain.\n\nThe resolver also normalises input — a missing protocol is prefixed with\nhttps, and paths and trailing slashes are reduced to the origin — so a\npasted value like \"portfolio.vercel.app/\" resolves correctly instead of\nbreaking metadata.\n\nVerified: build passes with the variable empty, and with it empty\nalongside VERCEL_PROJECT_PRODUCTION_URL the generated robots.txt and\nsitemap.xml carry the correct absolute domain.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"d71683fd8a0d64e310b935354431cdca75f6f86b","url":"https://api.github.com/repos/rohit-manora/portfolio/git/trees/d71683fd8a0d64e310b935354431cdca75f6f86b"},"url":"https://api.github.com/repos/rohit-manora/portfolio/git/commits/75d2a67f54b5957f33bea24e1c0f216fcc3d6c89","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/87164320?v=4","events_url":"https://api.github.com/users/rohit-manora/events{/privacy}","followers_url":"https://api.github.com/users/rohit-manora/followers","following_url":"https://api.github.com/users/rohit-manora/following{/other_user}","gists_url":"https://api.github.com/users/rohit-manora/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/rohit-manora","id":87164320,"login":"rohit-manora","node_id":"MDQ6VXNlcjg3MTY0MzIw","organizations_url":"https://api.github.com/users/rohit-manora/orgs","received_events_url":"https://api.github.com/users/rohit-manora/received_events","repos_url":"https://api.github.com/users/rohit-manora/repos","site_admin":false,"starred_url":"https://api.github.com/users/rohit-manora/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/rohit-manora/subscriptions","type":"User","url":"https://api.github.com/users/rohit-manora","user_view_type":"public"},"html_url":"https://github.com/rohit-manora/portfolio/commit/75d2a67f54b5957f33bea24e1c0f216fcc3d6c89","node_id":"C_kwDOUXOxJ9oAKDc1ZDJhNjdmNTRiNTk1N2YzM2JlYTI0ZTFjMGYyMTZmY2MzZDZjODk","parents":[{"html_url":"https://github.com/rohit-manora/portfolio/commit/d67a11a9e9d767ce97762f4b866132088226f2a5","sha":"d67a11a9e9d767ce97762f4b866132088226f2a5","url":"https://api.github.com/repos/rohit-manora/portfolio/commits/d67a11a9e9d767ce97762f4b866132088226f2a5"}],"sha":"75d2a67f54b5957f33bea24e1c0f216fcc3d6c89","url":"https://api.github.com/repos/rohit-manora/portfolio/commits/75d2a67f54b5957f33bea24e1c0f216fcc3d6c89"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/87164320?v=4","events_url":"https://api.github.com/users/rohit-manora/events{/privacy}","followers_url":"https://api.github.com/users/rohit-manora/followers","following_url":"https://api.github.com/users/rohit-manora/following{/other_user}","gists_url":"https://api.github.com/users/rohit-manora/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/rohit-manora","id":87164320,"login":"rohit-manora","node_id":"MDQ6VXNlcjg3MTY0MzIw","organizations_url":"https://api.github.com/users/rohit-manora/orgs","received_events_url":"https://api.github.com/users/rohit-manora/received_events","repos_url":"https://api.github.com/users/rohit-manora/repos","site_admin":false,"starred_url":"https://api.github.com/users/rohit-manora/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/rohit-manora/subscriptions","type":"User","url":"https://api.github.com/users/rohit-manora","user_view_type":"public"},"comments_url":"https://api.github.com/repos/rohit-manora/portfolio/commits/d67a11a9e9d767ce97762f4b866132088226f2a5/comments","commit":{"author":{"date":"2026-09-11T17:48:09Z","email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"comment_count":0,"committer":{"date":"2026-09-11T17:48:09Z","email":"87164320+rohit-manora@users.noreply.github.com","name":"Rohit Manora"},"message":"Initial commit: portfolio site for Rohit Manora\n\nSingle-page portfolio built around two interactive artifacts rather than\nprose: a Carnival UK microfrontend architecture explorer and a\nStreamAnalytix pipeline visualisation.\n\nStack\n- Next.js 16 (App Router) with React Server Components by default\n- TypeScript strict, plus noUncheckedIndexedAccess and\n  exactOptionalPropertyTypes\n- Tailwind CSS v4 with design tokens in @theme\n- React Three Fiber for the hero lattice; Framer Motion; Lucide\n\nContent layer\nAll copy lives in data/ as typed TypeScript; nothing is hardcoded in JSX.\nEvery entry carries a source field (\"A\" = Publicis Sapient profile PDF,\n\"B\" = personal CV PDF, \"A+B\", or \"user\"). TechId and EngagementId are\nstring-literal unions, so a typo in a usedOn array is a compile error.\n\nContent integrity rules enforced by the data model:\n- Every metric renders with its provenance label\n- No per-module descriptions for the Carnival microfrontends; the resume\n  names the eight modules but describes none, so the detail panel shows\n  only facts true of every module\n- The AWS entry is marked a Udemy course, not an AWS certification\n- No screenshots; project visuals are generative SVG motifs\n\n3D\nThe hero scene renders in three draw calls with no post-processing.\nTier-gated: full on desktop, reduced on tablet, static SVG on mobile and\nunder prefers-reduced-motion. three.js sits behind a dynamic import and\nis absent from the prerendered HTML. The frameloop pauses off-screen.\n\nAccessibility\nSemantic landmarks, one h1 with unbroken hierarchy, skip link, full\nkeyboard operation including both graph visualisations, a hidden table\nmirroring the architecture graph, focus trap on the mobile menu, and a\nreduced-motion contract that freezes loops but keeps hover feedback.\n\nSEO\nMetadata API, canonical, Open Graph with a generated image, generated\nrobots.txt and sitemap.xml, and Person / WebSite / ProfilePage JSON-LD.\n\nVerified: tsc clean, eslint clean, next build succeeds, npm audit reports\nno vulnerabilities. Initial JS measures 229KB gzipped; the 840KB three.js\nchunk is deferred.\n\nDesign specification of record is PORTFOLIO_PLAN.md.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"5bd12b24a4b1578bc98168504a044cb698186918","url":"https://api.github.com/repos/rohit-manora/portfolio/git/trees/5bd12b24a4b1578bc98168504a044cb698186918"},"url":"https://api.github.com/repos/rohit-manora/portfolio/git/commits/d67a11a9e9d767ce97762f4b866132088226f2a5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/87164320?v=4","events_url":"https://api.github.com/users/rohit-manora/events{/privacy}","followers_url":"https://api.github.com/users/rohit-manora/followers","following_url":"https://api.github.com/users/rohit-manora/following{/other_user}","gists_url":"https://api.github.com/users/rohit-manora/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/rohit-manora","id":87164320,"login":"rohit-manora","node_id":"MDQ6VXNlcjg3MTY0MzIw","organizations_url":"https://api.github.com/users/rohit-manora/orgs","received_events_url":"https://api.github.com/users/rohit-manora/received_events","repos_url":"https://api.github.com/users/rohit-manora/repos","site_admin":false,"starred_url":"https://api.github.com/users/rohit-manora/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/rohit-manora/subscriptions","type":"User","url":"https://api.github.com/users/rohit-manora","user_view_type":"public"},"html_url":"https://github.com/rohit-manora/portfolio/commit/d67a11a9e9d767ce97762f4b866132088226f2a5","node_id":"C_kwDOUXOxJ9oAKGQ2N2ExMWE5ZTlkNzY3Y2U5Nzc2MmY0Yjg2NjEzMjA4ODIyNmYyYTU","parents":[],"sha":"d67a11a9e9d767ce97762f4b866132088226f2a5","url":"https://api.github.com/repos/rohit-manora/portfolio/commits/d67a11a9e9d767ce97762f4b866132088226f2a5"}],"requestUrl":"https://api.github.com/repos/rohit-manora/portfolio/commits?per_page=100&page=1&sha=75d2a67f54b5957f33bea24e1c0f216fcc3d6c89&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A44%3A21.330Z"}');
